def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_max_prime(numbers):
    """Find the largest prime number in a list of integers."""
    max_prime = -1
    for num in numbers:
        if is_prime(num) and num > max_prime:
            max_prime = num
    return max_prime

