def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary with keys representing the hierarchy of nested keys.

    :param d: The dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator to use between keys.
    :return: A flattened dictionary.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

# Example usage:
data_dict = {"A": {"B": 1, "C": {"D": 2}}}
flattened_dict = flatten_dict(data_dict)
print(flattened_dict)  # Output: {'A.B': 1, 'A.C.D': 2}
