def findDuplicates(nums):
    """
    Finds all integers that appear more than once in the input list and returns them in a sorted list without duplicates.

    :param nums: List[int] - A list of integers.
    :return: List[int] - A sorted list of integers that appear more than once in the input list.
    """
    seen = set()
    duplicates = set()
    for num in nums:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)
    return sorted(list(duplicates))
