class Graph:
    def __init__(self):
        self.graph = {}  # Dictionary to store graph: key is the node, value is a list of adjacent nodes

    def add_node(self, node):
        """Add a node to the graph."""
        if node not in self.graph:
            self.graph[node] = []

    def add_edge(self, node1, node2):
        """Add an undirected edge between two nodes."""
        if node1 in self.graph:
            self.graph[node1].append(node2)
        else:
            self.graph[node1] = [node2]

        if node2 in self.graph:
            self.graph[node2].append(node1)
        else:
            self.graph[node2] = [node1]

    def remove_node(self, node):
        """Remove a node from the graph along with all edges connected to it."""
        if node in self.graph:
            del self.graph[node]
            for n in self.graph:
                self.graph[n] = [v for v in self.graph[n] if v != node]

    def remove_edge(self, node1, node2):
        """Remove an undirected edge between two nodes."""
        if node1 in self.graph:
            self.graph[node1] = [v for v in self.graph[node1] if v != node2]
        if node2 in self.graph:
            self.graph[node2] = [v for v in self.graph[node2] if v != node1]

    def dfs(self, start, goal, path=None):
        """Perform a DFS to find a path from start to goal."""
        if path is None:
            path = [start]

        if start in self.graph:
            if start == goal:
                return path

            for neighbor in self.graph[start]:
                if neighbor not in path:
                    new_path = self.dfs(neighbor, goal, path + [neighbor])
                    if new_path:
                        return new_path

        return None  # Goal not reachable from start
