def count_integers(lst):
    """
    Constructs a dictionary with integers as keys and their counts as values,
    excluding integers that appear less than three times.

    :param lst: List of lists containing integers.
    :return: Dictionary with integers as keys and their counts as values.
    """
    count_dict = {}
    for sublist in lst:
        for num in sublist:
            if num in count_dict:
                count_dict[num] += 1
            else:
                count_dict[num] = 1

    return {k: v for k, v in count_dict.items() if v >= 3}

