def is_valid_ipv4(ip: str) -> bool:
    """
    Determines if the given string is a valid IPv4 address.

    :param ip: A string representing the IPv4 address.
    :return: True if the string is a valid IPv4 address, otherwise False.
    """
    parts = ip.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
        if part != str(num):
            return False

    return True
