def is_bipartite(graph):
    """
    Determines if the given graph is bipartite using Depth-First Search (DFS).

    :param graph: A dictionary representing the graph where keys are node identifiers
                  and values are lists of adjacent nodes.
    :return: True if the graph is bipartite, False otherwise.
    """
    color_map = {}

    def dfs(node, color):
        if node in color_map:
            return color_map[node] == color
        color_map[node] = color
        opposite_color = 1 - color
        return all(dfs(neighbor, opposite_color) for neighbor in graph[node])

    for node in graph:
        if node not in color_map and not dfs(node, 0):
            return False

    return True

