def find_longest_common_prefix(strs):
    """
    Finds the longest common prefix among all strings in the given list.

    :param strs: List of strings
    :return: Longest common prefix as a string
    """
    if not strs:
        return ''

    shortest = min(strs, key=len)

    for i, char in enumerate(shortest):
        for other in strs:
            if other[i] != char:
                return shortest[:i]

    return shortest
