def find_mode(numbers):
    """
    Returns the mode of the list of integers, which is the integer that appears most frequently.
    If there are multiple integers with the same highest frequency, returns the smallest integer.
    Returns None if the list is empty.

    :param numbers: List of integers
    :return: Integer representing the mode or None if the list is empty
    """
    if not numbers:
        return None

    frequency = {}
    for number in numbers:
        if number in frequency:
            frequency[number] += 1
        else:
            frequency[number] = 1

    max_frequency = max(frequency.values())
    modes = [number for number, count in frequency.items() if count == max_frequency]

    return min(modes)
